package com.mvt.backApp.user.service;
import com.mvt.backApp.common.exception.ApiException;import com.mvt.backApp.user.entity.*;import com.mvt.backApp.user.repository.EmailVerificationChallengeRepository;
import lombok.RequiredArgsConstructor;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.security.SecureRandom;import java.time.LocalDateTime;import java.util.Locale;
@Service @RequiredArgsConstructor public class EmailOtpService {
 private final EmailVerificationChallengeRepository repository;private final EmailDeliveryService delivery;private final PasswordEncoder encoder;private final SecureRandom random=new SecureRandom();
 @Transactional public void send(String raw,OtpPurpose purpose){String email=normalize(raw);repository.findTopByEmailAndPurposeAndConsumedAtIsNullOrderByCreatedAtDesc(email,purpose).ifPresent(last->{if(last.getCreatedAt()!=null&&last.getCreatedAt().isAfter(LocalDateTime.now().minusSeconds(60)))throw new ApiException("OTP_RATE_LIMITED","error.otp.rateLimited",429);last.setConsumedAt(LocalDateTime.now());repository.save(last);});String otp=String.format("%06d",random.nextInt(1_000_000));EmailVerificationChallenge c=new EmailVerificationChallenge();c.setEmail(email);c.setPurpose(purpose);c.setOtpHash(encoder.encode(otp));c.setExpiresAt(LocalDateTime.now().plusMinutes(10));repository.save(c);delivery.sendRegistrationOtp(email,otp);}
 @Transactional public void verifyAndConsume(String raw,OtpPurpose purpose,String otp){EmailVerificationChallenge c=repository.findTopByEmailAndPurposeAndConsumedAtIsNullOrderByCreatedAtDesc(normalize(raw),purpose).orElseThrow(()->new ApiException("OTP_NOT_FOUND","error.otp.notFound",400));if(c.getExpiresAt().isBefore(LocalDateTime.now()))throw new ApiException("OTP_EXPIRED","error.otp.expired",400);if(c.getAttemptCount()>=5)throw new ApiException("OTP_ATTEMPTS_EXCEEDED","error.otp.attempts",400);c.setAttemptCount(c.getAttemptCount()+1);if(!encoder.matches(otp,c.getOtpHash())){repository.save(c);throw new ApiException("OTP_INVALID","error.otp.invalid",400);}c.setConsumedAt(LocalDateTime.now());repository.save(c);}
 private String normalize(String s){return s.trim().toLowerCase(Locale.ROOT);} }
